.envio-avatar img{ width: 100%; height: 100%; object-fit: cover; display: none; }
.envio-avatar.com-imagem{ border-style: solid; border-color: var(--sun); }
.envio-avatar.com-imagem .avatar-provisorio{ display: none; }
.envio-avatar.com-imagem img{ display: block; }
.selo-avatar{
  position: absolute; bottom: 0; right: 0;
  width: 30px; height: 30px; border-radius: 50%;
  background: var(--sun); color: var(--navy-deep);
  display: flex; align-items: center; justify-content: center;
  border: 3px solid var(--navy-deep);
}
.dica-avatar{ display: block; margin-top: 10px; font-size: .78rem; color: rgba(255,255,255,.62); text-align: center; }

.campo-erro{ display: none; margin-top: 7px; font-size: .78rem; color: #FF8A72; }
.campo.com-erro input, .campo.com-erro select{ outline: 2px solid #E4574B; }
.campo.com-erro .campo-erro{ display: block; }

.campo-caixa-selecao{
