.campo-caixa-selecao a{ color: var(--paper); text-decoration: underline; }
.perfil-conteudo .campo-caixa-selecao, .empresa-destaque .campo-caixa-selecao{ color: var(--ink-soft); }
.perfil-conteudo .campo-caixa-selecao a, .empresa-destaque .campo-caixa-selecao a{ color: var(--terracotta); }

.campo-dica{ display:block; margin-top: 6px; font-size: .78rem; color: rgba(255,255,255,.6); }

.perfil-conteudo .campo label,
.caixa-modal .campo label{ color: var(--heading); }
.perfil-conteudo .campo-dica,
.caixa-modal .campo-dica{ color: var(--ink-soft); }
