.chip-atributo{
  display: flex; align-items: center; gap: 10px;
  padding: 12px 16px;
  border-radius: 16px;
  border: 1.5px solid rgba(255,255,255,.18);
  background: rgba(255,255,255,.06);
  color: rgba(255,255,255,.9);
  font-family: var(--font-body);
  font-weight: 600;
  font-size: .87rem;
