}
.chip-atributo:hover{ border-color: var(--sun); background: rgba(255,255,255,.12); transform: translateY(-2px); }
.chip-atributo::before{
  content: '';
  width: 20px; height: 20px; flex-shrink: 0; box-sizing: border-box;
  border-radius: 50%; border: 2px solid rgba(255,255,255,.4);
  background: rgba(255,255,255,.05);
  display: flex; align-items: center; justify-content: center;
  transition: background-color .18s ease, border-color .18s ease;
}
.chip-atributo .chip-marca{ display: none; }
