  box-shadow: var(--shadow-pop);
}
.chip-atributo.selecionado::before{
  content: '\2713'; background: var(--sun); border-color: var(--sun); color: var(--navy-deep);
  font-size: .72rem; font-weight: 800; line-height: 1;
}
