.perfil-conteudo .chip-atributo.selecionado::before{ background: var(--terracotta); border-color: var(--terracotta); color: var(--paper); }

.perfil-destaque{ padding: 64px 0 46px; }
.perfil-resumo{ display:flex; align-items:center; gap: 26px; flex-wrap: wrap; }
