#intro .logo{ width:auto; max-width:min(460px,80vw); max-height:68vh; }
@media (min-width:1700px){ #intro .logo{ max-width:min(620px,80vw); } #intro .bola{ width:56px; height:56px; } }
@media (max-width:360px){ #intro .bola{ width:38px; height:38px; } }

@media (prefers-reduced-motion:reduce){ html{ scroll-behavior:auto; } }

:root{
  --chao-n:2;
  --chao-img:url("data:image/png;base64,");
  --passaro-img:url("data:image/png;base64,");
}
@media (max-width:820px){ :root{ --chao-n:1; } }
@media (min-width:1701px){ :root{ --chao-n:3; } }
@media (min-width:2501px){ :root{ --chao-n:4; } }

.destaque-inicio::after{ display:none; }
.faixa-logos{ position:relative; margin-top:56px; }
.faixa-logos::before{
  content:''; position:absolute; left:0; right:0; bottom:100%; z-index:1; pointer-events:none;
  height:calc(100vw / var(--chao-n) * .12);
  background-color:var(--tinta);
  -webkit-mask:var(--chao-img) left bottom / calc(100% / var(--chao-n)) 100% repeat-x;
          mask:var(--chao-img) left bottom / calc(100% / var(--chao-n)) 100% repeat-x;
}

.faixa-logos p{ margin-left:auto; margin-right:auto; }

.passaro-cordel{
  position:absolute; z-index:2; pointer-events:none;
  width:clamp(46px,6vw,78px); height:clamp(32px,4.22vw,55px);
  background-color:var(--tinta); opacity:.78;
  -webkit-mask:var(--passaro-img) center / contain no-repeat;
          mask:var(--passaro-img) center / contain no-repeat;
}
.passaro-cordel.creme{ background-color:#F5E9C8; opacity:.5; }
.passaro-cordel.olha-esq{ transform:scaleX(-1); }

.pc-afiliados{ right:4%; top:10px; }
.pc-caminhos{ left:3%; top:16px; }
.destaque-interno > .pc-sobre{ left:5%; bottom:20px; }
.colagem-destaque > .pc-vagas{ right:3%; bottom:20px; width:clamp(40px,5vw,64px); height:clamp(28px,3.5vw,45px); }
@media (max-width:560px){
  .pc-caminhos{ left:4%; top:10px; }
  .destaque-interno > .pc-sobre{ bottom:14px; }
}
.colagem-destaque{ position:relative; }
.destaque-interno{ position:relative; }
.rodape-logo{ display:block; width:clamp(150px,18vw,210px); height:auto; margin:0 0 6px -6px; }

[data-page="cadastro"] .cartao-autenticacao{ --laranja-destaque: #FF7A1A; }
[data-page="cadastro"] .cartao-autenticacao h1::after{ content: ""; display: block; width: 56px; height: 6px; margin-top: 12px; border-radius: 999px; background: var(--laranja-destaque); }
[data-page="cadastro"] .alternador-tipo-conta button.ativo{ background: var(--laranja-destaque); color: var(--navy-deep); }
[data-page="cadastro"] .botao-sol{ background: var(--laranja-destaque); color: var(--navy-deep); }
[data-page="cadastro"] .nota-rodape-autenticacao a{ color: var(--laranja-destaque); }